import { Inter, Noto_Sans_KR } from "next/font/google";

export const inter = Inter({
  weight: ["400", "500", "600", "700"],
  subsets: ["latin"],
  variable: "--font-inter",
  display: "swap",
});

export const notoSansKR = Noto_Sans_KR({
  weight: ["400", "500", "700"],
  subsets: ["latin"],
  variable: "--font-noto-sans-kr",
  display: "swap",
});

"use client";

import { useEffect, useRef } from "react";

/** Per-frame lerp toward the pointer, normalized to 60fps in the loop. */
const PARALLAX_LERP = 0.045;

/**
 * Drives `--drm-px` / `--drm-py` (each −1…1) on the referenced element — the
 * weightless depth of the cloud sky. styles.css multiplies these into
 * capped translations at three depths: the far sky barely moves, the middle
 * layer carries the drift, the nearest puffs read at arm's length. The lerp
 * is deliberately slower than a tracking parallax (0.045 vs the usual 0.08):
 * clouds do not chase the pointer, they settle after it.
 *
 * Fine pointers only — on touch the layers simply rest (the ambient cloud-bob
 * animation carries the life instead), and under reduced motion this hook
 * does nothing; the CSS fallback for both variables is 0.
 */
export function usePointerParallax<T extends HTMLElement>(disabled: boolean) {
  const ref = useRef<T | null>(null);

  useEffect(() => {
    const el = ref.current;
    if (!el || disabled) return;
    if (!window.matchMedia("(hover: hover) and (pointer: fine)").matches) {
      return;
    }

    let raf = 0;
    let running = false;
    let inView = true;
    let x = 0;
    let y = 0;
    let tx = 0;
    let ty = 0;
    let last = 0;

    const step = (now: number) => {
      raf = requestAnimationFrame(step);
      const dt = Math.min(now - last, 48);
      last = now;
      const k = PARALLAX_LERP * (dt / 16.7);
      x += (tx - x) * k;
      y += (ty - y) * k;
      el.style.setProperty("--drm-px", x.toFixed(4));
      el.style.setProperty("--drm-py", y.toFixed(4));
    };

    const start = () => {
      if (running) return;
      running = true;
      last = performance.now();
      raf = requestAnimationFrame(step);
    };
    const stop = () => {
      running = false;
      cancelAnimationFrame(raf);
    };

    const onMove = (ev: PointerEvent) => {
      if (ev.pointerType !== "mouse" && ev.pointerType !== "pen") return;
      const r = el.getBoundingClientRect();
      tx = Math.max(-1, Math.min(1, ((ev.clientX - r.left) / r.width) * 2 - 1));
      ty = Math.max(-1, Math.min(1, ((ev.clientY - r.top) / r.height) * 2 - 1));
    };
    const onLeave = () => {
      tx = 0;
      ty = 0;
    };
    el.addEventListener("pointermove", onMove);
    el.addEventListener("pointerleave", onLeave);

    const io = new IntersectionObserver((hits) => {
      inView = hits[hits.length - 1].isIntersecting;
      if (inView && !document.hidden) start();
      else stop();
    });
    io.observe(el);

    const onVisibility = () => {
      if (document.hidden) stop();
      else if (inView) start();
    };
    document.addEventListener("visibilitychange", onVisibility);

    return () => {
      stop();
      io.disconnect();
      el.removeEventListener("pointermove", onMove);
      el.removeEventListener("pointerleave", onLeave);
      document.removeEventListener("visibilitychange", onVisibility);
      el.style.removeProperty("--drm-px");
      el.style.removeProperty("--drm-py");
    };
  }, [disabled]);

  return ref;
}

"use client";

import { useSyncExternalStore } from "react";

const QUERY = "(prefers-reduced-motion: reduce)";

function subscribe(onChange: () => void): () => void {
  const mql = window.matchMedia(QUERY);
  mql.addEventListener("change", onChange);
  return () => mql.removeEventListener("change", onChange);
}

function getSnapshot(): boolean {
  return window.matchMedia(QUERY).matches;
}

function getServerSnapshot(): boolean {
  return false;
}

/**
 * True when the OS asks for reduced motion.
 * SSR-safe: the server snapshot is `false`; on the client the real value is
 * read synchronously, and live changes to the setting re-render immediately.
 */
export function usePrefersReducedMotion(): boolean {
  return useSyncExternalStore(subscribe, getSnapshot, getServerSnapshot);
}

"use client";

import { useEffect, useRef } from "react";
import { usePrefersReducedMotion } from "./usePrefersReducedMotion";

/**
 * Direction-aware clip-path reveal.
 *
 * Attach the returned ref to a block you want wiped in by a hard geometric
 * cut (the brutalist equivalent of a fade). When the block enters the
 * viewport, `is-revealed` is added to it; `styles.css` drives the
 * inset/polygon clip from `--rave-reveal-dir`. The reveal happens once and
 * the observer disconnects — a section does not get to re-wipe every time
 * it scrolls back into frame.
 *
 * No-JS / SSR: the page ships already visible (`rave-reveal` with no
 * `rave-js` ancestor is static, clip-path: none). The pre-reveal hidden
 * state is gated behind `.rave-js .rave-reveal` so the SSR markup is the
 * completed flyer.
 */
export function useReveal<T extends HTMLElement = HTMLElement>() {
  const ref = useRef<T | null>(null);
  const reduced = usePrefersReducedMotion();

  useEffect(() => {
    const el = ref.current;
    if (!el) return;

    // Reduced motion: leave the SSR-visible state alone. No wipe.
    if (reduced) return;

    const io = new IntersectionObserver(
      (entries) => {
        for (const entry of entries) {
          if (entry.isIntersecting) {
            entry.target.classList.add("is-revealed");
            io.unobserve(entry.target);
          }
        }
      },
      { rootMargin: "-8% 0px -8% 0px", threshold: 0.12 },
    );
    io.observe(el);
    return () => io.disconnect();
  }, [reduced]);

  return ref;
}

"use client";

import { useEffect, useRef } from "react";

/**
 * Drives a 0→1 scroll progress for a pinned chashitsu (tea-preparation
 * scene), written to the element as the `--ch-scrub` custom property. The
 * chasen whisk consumes it in CSS:
 *   stroke-dashoffset: calc(1 - var(--ch-scrub, 1))
 * on pathLength=1 bamboo-tine paths — so the whisk draws exactly as far as
 * the guest has scrolled, and the bowl's matcha surface blooms in only as
 * the preparation completes. The whole ceremony is paced so the whisk never
 * moves faster than the hand that summoned it.
 *
 * Discipline (rubric gate G3):
 * - All geometry is measured inside rAF: one getBoundingClientRect read,
 *   then one custom-property write — read before write, no layout thrash.
 * - The raw progress is lerp-smoothed with a dt-normalized factor
 *   (1 - 0.88^(dt/16.7)), so a 120Hz display does not scrub twice as fast
 *   as a 60Hz one. Half-life ≈ 5.4 frames.
 * - An IntersectionObserver starts/stops the loop, so an offscreen
 *   chashitsu costs zero frames. A visibilitychange listener also stops it
 *   when the tab is hidden.
 * - Disabled (reduced motion) or never mounted (no JS): the hook writes
 *   `--ch-scrub: 1` once and the CSS default of 1 leaves every tine drawn
 *   and the bowl full — a completed preparation, statically waiting.
 */
export function useScrollProgress<T extends HTMLElement>(disabled: boolean) {
  const ref = useRef<T | null>(null);

  useEffect(() => {
    const el = ref.current;
    if (!el) return;

    if (disabled) {
      el.style.setProperty("--ch-scrub", "1");
      return;
    }

    let raf = 0;
    let last = 0;
    let value: number | null = null;

    const frame = (now: number) => {
      raf = requestAnimationFrame(frame);
      const dt = Math.min(Math.max(now - last, 1), 48);
      last = now;

      // Read phase: one rect, one viewport height.
      const rect = el.getBoundingClientRect();
      const vh = window.innerHeight || 1;

      // The scrub runs from "scene center at 62% of the viewport" across
      // 90% of the scene's height, capped at ~1.2 viewports so tall
      // single-column (mobile) chashitsu still finish while in view.
      const center = rect.top + rect.height / 2;
      const span = Math.max(Math.min(rect.height * 0.9, vh * 1.2), 1);
      const raw = (vh * 0.62 - center) / span;
      const target = Math.min(1, Math.max(0, raw));

      if (value === null) {
        value = target; // first frame: no animated catch-up flash
      } else {
        value += (target - value) * (1 - Math.pow(0.88, dt / 16.7));
        if (Math.abs(target - value) < 0.0005) value = target;
      }

      // Write phase.
      el.style.setProperty("--ch-scrub", value.toFixed(4));
    };

    const start = () => {
      if (raf) return;
      last = performance.now();
      raf = requestAnimationFrame(frame);
    };
    const stop = () => {
      if (!raf) return;
      cancelAnimationFrame(raf);
      raf = 0;
    };

    const onVisibility = () => {
      if (document.hidden) stop();
      else start();
    };
    document.addEventListener("visibilitychange", onVisibility);

    if (!("IntersectionObserver" in window)) {
      start();
      return () => {
        stop();
        document.removeEventListener("visibilitychange", onVisibility);
      };
    }

    const io = new IntersectionObserver(
      (hits) => {
        for (const hit of hits) {
          if (hit.isIntersecting) start();
          else stop();
        }
      },
      { rootMargin: "25% 0px 25% 0px" },
    );
    io.observe(el);

    return () => {
      stop();
      io.disconnect();
      document.removeEventListener("visibilitychange", onVisibility);
    };
  }, [disabled]);

  return ref;
}

/* FLOW 흐름 — river of words · kinetic-typography
   sky / paper / drift · letters flow like water */

.flow-root {
  --flow-bg: #f0f9ff;
  --flow-bg-deep: #e0f2fe;
  --flow-ink: #0c4a6e;
  --flow-ink-soft: #0369a1;
  --flow-accent: #0ea5e9;
  --flow-accent-soft: rgba(14, 165, 233, 0.15);
  --flow-font: var(--font-inter), var(--font-noto-sans-kr), sans-serif;

  position: relative;
  min-height: 100vh;
  background: linear-gradient(180deg, var(--flow-bg) 0%, var(--flow-bg-deep) 100%);
  color: var(--flow-ink);
  font-family: var(--flow-font);
  font-size: clamp(15px, 0.5vw + 13px, 17px);
  line-height: 1.75;
  overflow-x: hidden;
  overflow-x: clip;
}

/* A faint water surface — concentric ripples that breathe slowly, the only
   ambient texture. Pure CSS, paused under reduced motion. */
.flow-root::before {
  content: "";
  position: fixed;
  inset: -20%;
  z-index: 0;
  pointer-events: none;
  background:
    radial-gradient(40% 30% at 30% 20%, rgba(14,165,233,0.06), transparent 60%),
    radial-gradient(45% 35% at 75% 70%, rgba(14,165,233,0.05), transparent 60%);
  animation: flow-surface 18s ease-in-out infinite alternate;
}
@keyframes flow-surface {
  to { transform: translate3d(2%, -1%, 0) scale(1.04); }
}
@media (prefers-reduced-motion: reduce) {
  .flow-root::before { animation: none; }
}

.flow-root :lang(ko) { font-family: var(--font-noto-sans-kr), sans-serif; }
.flow-root ::selection { background: var(--flow-accent); color: #fff; }
.flow-root :focus-visible { outline: 2px solid var(--flow-accent); outline-offset: 4px; }

/* Reveal gating */
.flow-js [data-reveal] {
  opacity: 0;
  transform: translateY(24px);
  transition: opacity 900ms cubic-bezier(0.16,1,0.3,1), transform 900ms cubic-bezier(0.16,1,0.3,1);
}
.flow-js [data-reveal].is-visible { opacity: 1; transform: none; }
@media (prefers-reduced-motion: reduce) {
  .flow-js [data-reveal] { opacity: 1; transform: none; transition: none; }
}

/* pointer-parallax layer */
.flow-parallax {
  position: relative;
  z-index: 1;
  transition: transform 600ms cubic-bezier(0.16,1,0.3,1);
  will-change: transform;
}
@media (prefers-reduced-motion: reduce) {
  .flow-parallax { transform: none !important; transition: none; }
}

/* Hero */
.flow-hero {
  padding: clamp(80px, 18vh, 160px) clamp(20px, 5vw, 60px) clamp(40px, 8vh, 80px);
  text-align: center;
}
.flow-kicker {
  font-size: 0.72rem;
  text-transform: uppercase;
  letter-spacing: 0.22em;
  color: var(--flow-accent);
  margin: 0 0 30px;
}
.flow-title {
  font-weight: 700;
  font-size: clamp(4rem, 14vw, 10rem);
  line-height: 0.9;
  margin: 0 0 24px;
  display: flex;
  justify-content: center;
  flex-wrap: wrap;
  gap: 0.02em;
}
/* char-split-reveal: each glyph drifts in from the side, staggered */
.flow-glyph {
  display: inline-block;
  opacity: 0;
  transform: translateX(-40px) skewX(-8deg);
}
.flow-js .flow-glyph {
  animation: flow-glyph-in 1100ms cubic-bezier(0.16,1,0.3,1) both;
  animation-delay: calc(var(--flow-i, 0) * 140ms + 200ms);
}
@keyframes flow-glyph-in {
  to { opacity: 1; transform: translateX(0) skewX(0); }
}
@media (prefers-reduced-motion: reduce) {
  .flow-glyph { opacity: 1; transform: none; animation: none; }
}
.flow-title__ko {
  display: block;
  width: 100%;
  font-size: 0.32em;
  color: var(--flow-ink-soft);
  margin-top: 8px;
  font-weight: 500;
}
.flow-sub {
  max-width: 540px;
  margin: 0 auto;
  color: var(--flow-ink-soft);
  font-size: clamp(0.95rem, 1.6vw, 1.15rem);
  line-height: 1.7;
}

/* scroll-scrub-pinned: the verse section */
.flow-verse {
  position: sticky;
  top: 0;
  min-height: 100vh;
  min-height: 100svh;
  z-index: 2;
  display: flex;
  align-items: center;
  justify-content: center;
  padding: clamp(40px, 8vh, 80px) clamp(20px, 5vw, 60px);
  background:
    radial-gradient(80% 60% at 50% 50%, rgba(14,165,233,0.08), transparent 70%),
    var(--flow-bg-deep);
  border-top: 1px solid var(--flow-accent-soft);
  border-bottom: 1px solid var(--flow-accent-soft);
}
.flow-verse__inner {
  max-width: 680px;
  text-align: center;
}
.flow-verse__title {
  font-size: clamp(1.8rem, 4.5vw, 3rem);
  font-weight: 600;
  line-height: 1.2;
  margin: 0 0 48px;
  color: var(--flow-ink);
}
/* The stream of words flows horizontally, driven by --flow-scrub */
.flow-verse__stream {
  display: flex;
  gap: clamp(16px, 3vw, 32px);
  justify-content: center;
  flex-wrap: wrap;
  margin-bottom: 40px;
}
.flow-verse__word {
  font-size: clamp(1.5rem, 4vw, 2.5rem);
  font-weight: 500;
  color: var(--flow-accent);
  margin: 0;
  opacity: calc(0.3 + var(--flow-scrub, 0.5) * 0.7);
  transform: translateY(calc((1 - var(--flow-scrub, 0.5)) * 20px));
  transition: opacity 200ms, transform 200ms;
}
.flow-verse__en {
  font-size: clamp(0.9rem, 1.5vw, 1.05rem);
  color: var(--flow-ink-soft);
  margin: 0;
  line-height: 1.6;
}
.flow-verse__en em { font-style: italic; }

/* Features */
.flow-features {
  padding: clamp(60px, 12vh, 120px) clamp(20px, 5vw, 60px);
  display: grid;
  grid-template-columns: repeat(auto-fit, minmax(240px, 1fr));
  gap: clamp(32px, 5vw, 60px);
  max-width: 1000px;
  margin: 0 auto;
}
.flow-feature__h {
  font-size: 1.1rem;
  font-weight: 600;
  margin: 0 0 12px;
  color: var(--flow-ink);
}
.flow-feature__h :lang(ko) { color: var(--flow-accent); }
.flow-feature__p {
  margin: 0;
  color: var(--flow-ink-soft);
  font-size: 0.95rem;
  line-height: 1.6;
}

/* Footer */
.flow-foot {
  padding: clamp(48px, 10vh, 80px) clamp(20px, 5vw, 60px);
  text-align: center;
  border-top: 1px solid var(--flow-accent-soft);
  color: var(--flow-ink-soft);
  font-size: 0.82rem;
}
.flow-foot p { margin: 0 0 6px; }
